package cli

import (
	"regexp"
	"runtime/debug"
	"strings"

	"github.com/shadeform/shadeform-cli/internal/selfupdate"
)

// This file is hand-written, not generated by Speakeasy.
//
// Version in version.go is the number Speakeasy generated last, and it only
// moves on a regeneration. Releases are cut more often than that: every merge
// that changes shipped code is tagged as the next patch, so a release tag can
// run ahead of the generated number.
//
// Release archives are not affected, because GoReleaser stamps the tag in
// through ldflags (see cmd/shade/main.go). A binary from
//
//	go install github.com/shadeform/shadeform-cli/cmd/shade@v0.3.2
//
// has no ldflags, and without this file it would report the generated number
// in `shade version`, in the User-Agent, and to `shade update --check`, which
// would then offer the release that is already installed. Go records the
// module version such a binary was built from, so that is used instead. The
// same goes for a go build of a clean checkout of the tag.
//
// This runs before main, which still overrides Version when the release
// ldflags are present. BuildTime is not touched, so these binaries are still
// not release builds: no update notice, and no in-place update.
func init() {
	Version = moduleVersion(Version, debug.ReadBuildInfo)
}

// pseudoVersion matches the versions Go makes up for a commit that has no
// tag of its own, such as v0.3.2-0.20261124183000-ff9fbd98a1b2. It is the
// pattern golang.org/x/mod/module uses, minus build metadata.
var pseudoVersion = regexp.MustCompile(`^v[0-9]+\.(0\.0-|\d+\.\d+-([^+]*\.)?0\.)\d{14}-[A-Za-z0-9]+$`)

// moduleVersion returns the version this binary should report: the module
// version from the build info when that is a real release tag newer than the
// generated number, and the generated number otherwise.
//
// go build records a module version too, from version control. For a clean
// checkout of a release tag that is the tag itself, so such a build reports
// the tag just as go install does. Every other build from a checkout keeps
// the generated number: its module version is a pseudo-version when the
// commit is not tagged, carries "+dirty" when the tree has local changes, or
// is empty or "(devel)" when Go found no version control to read. None of
// those is a release.
func moduleVersion(generated string, readBuildInfo func() (*debug.BuildInfo, bool)) string {
	info, ok := readBuildInfo()
	if !ok || info == nil {
		return generated
	}
	v := info.Main.Version
	if v == "" || v == "(devel)" || strings.Contains(v, "+") || pseudoVersion.MatchString(v) {
		return generated
	}
	if !selfupdate.IsNewer(v, generated) {
		return generated
	}
	return strings.TrimPrefix(v, "v")
}
